2	
3	/// Settings' Verify button and its bookkeeping: which key and region a check
4	/// ran against, the transcriber it holds while it runs, and whether its
5	/// answer still describes what the window shows. A pure move out of
6	/// `SettingsWindowController.swift` (#58); the stored `verifying` stays there,
7	/// because an extension cannot store.
8	extension SettingsWindowController {
9	    struct VerificationInput: Equatable {
10	        let credential: String
11	        let region: AssemblyAIConfiguration.Region
12	        let base: URL
13	    }
14	
15	    struct Verification {
16	        let id: UUID
17	        let input: VerificationInput
18	        let transcriber: CloudTranscriber
19	    }
20	
21	    func effectiveCredential(storedCredential: String?) -> String? {
22	        let typed = keyField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
23	        if !typed.isEmpty { return typed }
24	        if let storedCredential { return storedCredential }
25	        guard let value = environment[AssemblyAIConfiguration.environmentKey] else { return nil }
26	        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
27	        return trimmed.isEmpty ? nil : trimmed
28	    }
29	
30	    func verificationInput(credential: String) throws -> VerificationInput {
31	        VerificationInput(
32	            credential: credential,
33	            region: AssemblyAIConfiguration.region(defaults: defaults),
34	            base: try AssemblyAIConfiguration.baseURL(defaults: defaults))
35	    }
36	
37	    func updateVerifyButton(credential: String?) {
38	        guard let credential else {
39	            verifyButton?.isEnabled = false
40	            return
41	        }
42	        if let verifying,
43	            (try? verificationInput(credential: credential)) == verifying.input
44	        {
45	            verifyButton?.isEnabled = false
46	        } else {
47	            verifyButton?.isEnabled = true
48	        }
49	    }
50	
51	    /// The cheapest authenticated call there is, against whatever key would
52	    /// be used for a real run: what is in the FIELD when somebody has typed
53	    /// one and not saved it yet, and the resolved credential otherwise.
54	    @objc func verifyClicked(_ sender: Any?) {
55	        verifying = nil
56	        guard let credential = effectiveCredential(storedCredential: store().read()) else {
57	            updateVerifyButton(credential: nil)
58	            say("No API key is set.", problem: false)
59	            return
60	        }
61	        let input: VerificationInput
62	        do {
63	            input = try verificationInput(credential: credential)
64	        } catch {
65	            updateVerifyButton(credential: credential)
66	            say(error.localizedDescription, problem: true)
67	            return
68	        }
69	        say("Checking…", problem: false)
70	        verifyButton.isEnabled = false
71	        // The cache directory and the media list are what a RUN needs and a
72	        // verify never touches; the temporary folder is the honest "nowhere".
73	        let transcriber = CloudTranscriber(
74	            client: AssemblyAIClient(base: input.base, credential: input.credential),
75	            cacheDirectory: URL(fileURLWithPath: NSTemporaryDirectory(), isDirectory: true),
76	            media: [:])
77	        let id = UUID()
78	        verifying = Verification(id: id, input: input, transcriber: transcriber)
79	        transcriber.verify { [weak self] answer in
80	            self?.completeVerification(answer, id: id, input: input)
81	        }
82	    }
83	
84	    private func completeVerification(
85	        _ answer: Result<Void, AssemblyAIClient.ClientError>,
86	        id: UUID, input: VerificationInput
87	    ) {
88	        guard verifying?.id == id else { return }
89	        verifying = nil
90	        let credential = effectiveCredential(storedCredential: store().read())
91	        updateVerifyButton(credential: credential)
92	        guard let credential,
93	            (try? verificationInput(credential: credential)) == input
94	        else {
95	            say("Settings changed since this check began. Verify again.", problem: false)
96	            return
97	        }
98	        switch answer {
99	        case .success:
100	            say("Key accepted", problem: false)
101	        case .failure(let error):
102	            say(error.localizedDescription, problem: true)
103	        }
104	    }
105	}
