1	import Foundation
2	
3	extension AssemblyAIClient {
4	    /// One paid submit. A lost or unreadable reply is resolved only from the
5	    /// newest account page, by the exact URL returned for this upload.
6	    func submit(_ request: TranscriptRequest) throws -> String {
7	        var post = self.request("POST", path: "/v2/transcript")
8	        post.setValue("application/json", forHTTPHeaderField: "content-type")
9	        post.httpBody = try JSONEncoder().encode(request)
10	        let reply = send(post)
11	        if let failure = classify(reply) {
12	            switch failure {
13	            case .noNetwork, .timedOut, .server, .malformed:
14	                return try recoverSubmission(audioURL: request.audioURL)
15	            default:
16	                throw failure
17	            }
18	        }
19	        if let response = try? JSONDecoder().decode(TranscriptResponse.self, from: reply.data),
20	            isSendableIdentifier(response.id)
21	        {
22	            return response.id
23	        }
24	        return try recoverSubmission(audioURL: request.audioURL)
25	    }
26	
27	    private struct SubmissionList: Decodable {
28	        let transcripts: [SubmissionListItem]
29	    }
30	
31	    private struct SubmissionListItem: Decodable {
32	        let id: String
33	        let audioURL: String
34	
35	        private enum CodingKeys: String, CodingKey {
36	            case id
37	            case audioURL = "audio_url"
38	        }
39	    }
40	
41	    /// A look either establishes one safe id, asks for another bounded look,
42	    /// or refuses. No row is retained and no unrelated id is requested.
43	    private func recoverSubmission(audioURL: URL) throws -> String {
44	        for look in 0..<max(1, tuning.submitRecoveryAttempts) {
45	            if look > 0 { sleep(tuning.submitRecoveryDelay, cancel: nil) }
46	            var get = request("GET", path: "/v2/transcript", query: "limit=200")
47	            get.timeoutInterval = tuning.submitRecoveryTimeout
48	            let reply = send(get)
49	            if let failure = classify(reply) {
50	                if case .keyRefused(let code) = failure {
51	                    throw ClientError.submissionUnresolved(authenticationStatus: code)
52	                }
53	                if failure.isRetriable || failure == .malformed("the request answered nothing at all") {
54	                    continue
55	                }
56	                throw ClientError.submissionUnresolved(authenticationStatus: nil)
57	            }
58	            guard let page = try? JSONDecoder().decode(SubmissionList.self, from: reply.data) else {
59	                continue
60	            }
61	            let matching = page.transcripts.filter { $0.audioURL == audioURL.absoluteString }
62	            if matching.contains(where: { !isSendableIdentifier($0.id) }) {
63	                throw ClientError.submissionUnresolved(authenticationStatus: nil)
64	            }
65	            let ids = Set(matching.map(\.id))
66	            if ids.count == 1, let id = ids.first { return id }
67	            if ids.count > 1 {
68	                throw ClientError.submissionUnresolved(authenticationStatus: nil)
69	            }
70	        }
71	        throw ClientError.submissionUnresolved(authenticationStatus: nil)
72	    }
73	}
